def solve(grid):
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # count colors
    cnt = Counter()
    for r in grid:
        cnt.update(r)

    # background is the most frequent color
    background = max(cnt, key=cnt.get)

    # collect candidate colors (excluding background)
    candidates = {c for c in cnt if c != background}

    # find the rectangular block (non-background) with largest area
    block_color = None
    block_bbox = None   # (min_r, max_r, min_c, max_c)
    max_area = -1

    for col in candidates:
        # collect positions of this color
        positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == col]
        if not positions:
            continue
        min_r = min(r for r, c in positions)
        max_r = max(r for r, c in positions)
        min_c = min(c for r, c in positions)
        max_c = max(c for r, c in positions)
        area = (max_r - min_r + 1) * (max_c - min_c + 1)
        if area > max_area:
            # verify it is a solid rectangle (no holes)
            if len(positions) == area:
                max_area = area
                block_color = col
                block_bbox = (min_r, max_r, min_c, max_c)

    # If no rectangle found, return input unchanged
    if block_color is None:
        return grid

    min_r, max_r, min_c, max_c = block_bbox

    # find aligned cells of other colors
    aligned = []  # each entry: (r, c, color, distance, direction)

    for r in range(rows):
        for c in range(cols):
            col = grid[r][c]
            if col == background or col == block_color:
                continue

            # horizontal alignment: same row as block, column outside
            if min_r <= r <= max_r:
                if c < min_c:
                    dist = min_c - c - 1
                    aligned.append((r, c, col, dist, 'left'))
                elif c > max_c:
                    dist = c - max_c - 1
                    aligned.append((r, c, col, dist, 'right'))
            # vertical alignment: same column as block, row outside
            elif min_c <= c <= max_c:
                if r < min_r:
                    dist = min_r - r - 1
                    aligned.append((r, c, col, dist, 'up'))
                elif r > max_r:
                    dist = r - max_r - 1
                    aligned.append((r, c, col, dist, 'down'))

    if not aligned:
        return grid

    max_dist = max(d for (_, _, _, d, _) in aligned)

    # draw lines for all cells having maximal distance
    for r, c, col, dist, direction in aligned:
        if dist != max_dist:
            continue
        if direction == 'left':
            for cc in range(c + 1, min_c):
                grid[r][cc] = col
        elif direction == 'right':
            for cc in range(max_c + 1, c):
                grid[r][cc] = col
        elif direction == 'up':
            for rr in range(r + 1, min_r):
                grid[rr][c] = col
        elif direction == 'down':
            for rr in range(max_r + 1, r):
                grid[rr][c] = col

    return grid

